// Package tuning holds the PostgreSQL parameters admins may change in the
// panel. Values are validated against fixed ranges by the panel and again by
// the worker, which writes them to an include file only PostgreSQL's OS user
// can write. Everything else in postgresql.conf stays generated by start.sh.
package tuning

import (
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type Kind int

const (
	Integer  Kind = iota
	Memory        // base unit kB
	Duration      // base unit ms
)

type Param struct {
	Name    string
	Kind    Kind
	Restart bool // needs a server restart, otherwise a reload is enough
	Help    string
	min     func(memMB int64) int64
	max     func(memMB int64) int64
	def     func(memMB int64) string
	defNote string // explains a computed or special default, shown after it
}

func fixed(n int64) func(int64) int64 { return func(int64) int64 { return n } }
func ofMemory(div int64) func(int64) int64 {
	return func(memMB int64) int64 { return memMB * 1024 / div }
}
func text(s string) func(int64) string { return func(int64) string { return s } }

// Params are the editable parameters, in display order. The defaults match start.sh.
var Params = []Param{
	{Name: "max_connections", Kind: Integer, Restart: true, min: fixed(20), max: fixed(2000), def: text("100"),
		Help: "Upper limit for all connections together. The connection limits of the roles should add up to less."},
	{Name: "shared_buffers", Kind: Memory, Restart: true, min: fixed(16 * 1024), max: func(m int64) int64 { return m * 1024 * 3 / 4 },
		def: func(m int64) string { return fmt.Sprintf("%dMB", m/4) }, defNote: "a quarter of the app memory",
		Help: "Cache shared by all connections. Empty follows the memory limit of the app."},
	{Name: "effective_cache_size", Kind: Memory, min: fixed(64 * 1024), max: fixed(1 << 30),
		def: func(m int64) string { return fmt.Sprintf("%dMB", m/2) }, defNote: "half of the app memory",
		Help: "Planner hint for the memory available for caching, allocates nothing."},
	{Name: "maintenance_work_mem", Kind: Memory, min: fixed(1024), max: ofMemory(2),
		def: func(m int64) string { return fmt.Sprintf("%dMB", m/16) }, defNote: "a sixteenth of the app memory",
		Help: "Memory for VACUUM, CREATE INDEX and the index builds of restores and imports."},
	{Name: "work_mem", Kind: Memory, min: fixed(64), max: ofMemory(4), def: text("4MB"),
		Help: "Memory per sort or hash step. One query can use it several times."},
	{Name: "statement_timeout", Kind: Duration, min: fixed(0), max: fixed(24 * 3600 * 1000), def: text("0"), defNote: "off",
		Help: "Cancels statements that run longer. Snapshots, restores and imports are not affected."},
	{Name: "idle_in_transaction_session_timeout", Kind: Duration, min: fixed(0), max: fixed(7 * 24 * 3600 * 1000), def: text("0"), defNote: "off",
		Help: "Ends sessions that keep a transaction open without doing anything."},
	{Name: "idle_session_timeout", Kind: Duration, min: fixed(0), max: fixed(7 * 24 * 3600 * 1000), def: text("0"), defNote: "off",
		Help: "Ends idle sessions. Breaks connection pools that keep idle connections open."},
}

func Lookup(name string) (Param, bool) {
	for _, p := range Params {
		if p.Name == name {
			return p, true
		}
	}
	return Param{}, false
}

func Names() []string {
	out := make([]string, len(Params))
	for i, p := range Params {
		out[i] = p.Name
	}
	return out
}

// Default is the value used when the field is empty.
func (p Param) Default(memMB int64) string { return p.def(memMB) }

// DefaultHint is Default with its explanation, for the form hint.
func (p Param) DefaultHint(memMB int64) string {
	if p.defNote == "" {
		return p.def(memMB)
	}
	return p.def(memMB) + ", " + p.defNote
}

// Range describes the allowed values for the form hint.
func (p Param) Range(memMB int64) string {
	return format(p.Kind, p.min(memMB)) + " to " + format(p.Kind, p.max(memMB))
}

var (
	integerRe  = regexp.MustCompile(`^[0-9]{1,12}$`)
	memoryRe   = regexp.MustCompile(`^([0-9]{1,12}) ?(?i)(kb|mb|gb|tb)$`)
	durationRe = regexp.MustCompile(`^([0-9]{1,12}) ?(ms|s|min|h|d)$`)
)

var (
	memoryUnits   = map[string]int64{"kB": 1, "MB": 1024, "GB": 1024 * 1024, "TB": 1024 * 1024 * 1024}
	memoryCanon   = map[string]string{"kb": "kB", "mb": "MB", "gb": "GB", "tb": "TB"}
	durationUnits = map[string]int64{"ms": 1, "s": 1000, "min": 60 * 1000, "h": 3600 * 1000, "d": 24 * 3600 * 1000}
)

// Normalize checks a value and returns it in the form written to the
// configuration file. The result only contains digits and a unit, so it
// needs no quoting.
func (p Param) Normalize(value string, memMB int64) (string, error) {
	value = strings.TrimSpace(value)
	var n, base int64
	var out string
	switch p.Kind {
	case Integer:
		if !integerRe.MatchString(value) {
			return "", fmt.Errorf("%s must be a whole number", p.Name)
		}
		n, _ = strconv.ParseInt(value, 10, 64)
		base, out = n, strconv.FormatInt(n, 10)
	case Memory:
		m := memoryRe.FindStringSubmatch(value)
		if m == nil {
			return "", fmt.Errorf("%s must be a size like 64MB or 1GB", p.Name)
		}
		n, _ = strconv.ParseInt(m[1], 10, 64)
		unit := memoryCanon[strings.ToLower(m[2])]
		base, out = n*memoryUnits[unit], strconv.FormatInt(n, 10)+unit
	case Duration:
		if value == "0" {
			return "0", nil
		}
		m := durationRe.FindStringSubmatch(value)
		if m == nil {
			return "", fmt.Errorf("%s must be 0 or a duration like 500ms, 30s, 10min or 2h", p.Name)
		}
		n, _ = strconv.ParseInt(m[1], 10, 64)
		base, out = n*durationUnits[m[2]], strconv.FormatInt(n, 10)+m[2]
	}
	if lo, hi := p.min(memMB), p.max(memMB); base < lo || base > hi {
		return "", fmt.Errorf("%s must be between %s and %s", p.Name, format(p.Kind, lo), format(p.Kind, hi))
	}
	return out, nil
}

func format(k Kind, n int64) string {
	switch k {
	case Memory:
		switch {
		case n%(1024*1024) == 0 && n >= 1024*1024:
			return strconv.FormatInt(n/(1024*1024), 10) + "GB"
		case n%1024 == 0 && n >= 1024:
			return strconv.FormatInt(n/1024, 10) + "MB"
		}
		return strconv.FormatInt(n, 10) + "kB"
	case Duration:
		switch {
		case n == 0:
			return "0"
		case n%(24*3600*1000) == 0:
			return strconv.FormatInt(n/(24*3600*1000), 10) + "d"
		case n%(3600*1000) == 0:
			return strconv.FormatInt(n/(3600*1000), 10) + "h"
		}
		return strconv.FormatInt(n, 10) + "ms"
	}
	return strconv.FormatInt(n, 10)
}

// Validate normalizes the non-empty values. Unknown names are an error, so a
// changed panel cannot smuggle other parameters past the worker.
func Validate(values map[string]string, memMB int64) (map[string]string, []error) {
	out := map[string]string{}
	var errs []error
	for name, v := range values {
		p, ok := Lookup(name)
		if !ok {
			errs = append(errs, fmt.Errorf("%s cannot be changed in the panel", name))
			continue
		}
		if strings.TrimSpace(v) == "" {
			continue
		}
		n, err := p.Normalize(v, memMB)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		out[name] = n
	}
	return out, errs
}

func Encode(values map[string]string) string {
	if len(values) == 0 {
		return ""
	}
	b, _ := json.Marshal(values)
	return string(b)
}

func Decode(s string) (map[string]string, error) {
	out := map[string]string{}
	if s == "" {
		return out, nil
	}
	err := json.Unmarshal([]byte(s), &out)
	return out, err
}

// Render returns the include file for postgresql.conf.
func Render(values map[string]string) string {
	var b strings.Builder
	b.WriteString("# Written by the panel worker from the admin settings. Changes here are overwritten.\n")
	for _, p := range Params {
		if v, ok := values[p.Name]; ok {
			fmt.Fprintf(&b, "%s = '%s'\n", p.Name, v)
		}
	}
	return b.String()
}

// MemoryMB reads the container memory limit like start.sh does.
func MemoryMB() int64 {
	limit := int64(2 * 1024 * 1024 * 1024)
	if b, err := os.ReadFile("/sys/fs/cgroup/memory.max"); err == nil {
		if v, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64); err == nil {
			limit = v
		}
	} else if b, err := os.ReadFile("/sys/fs/cgroup/memory/memory.limit_in_bytes"); err == nil {
		if v, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64); err == nil {
			limit = v
		}
	}
	return limit / 1024 / 1024
}
